MERGE INTO SCM_ADM_MNU_BTN_MPG_M t USING (SELECT 'SYS0011' MNU_ID, 'authority' SHT_NM, 'SEARCH' MNU_BTN_CD FROM DUAL) s
   ON (t.MNU_ID=s.MNU_ID AND t.SHT_NM=s.SHT_NM AND t.MNU_BTN_CD=s.MNU_BTN_CD)
